CREATE TABLE IF NOT EXISTS schema_versions(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,homepage TEXT NOT NULL,kind TEXT NOT NULL,category TEXT NOT NULL,language TEXT NOT NULL DEFAULT 'en',interval_minutes INTEGER NOT NULL DEFAULT 360,enabled INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'unverified',first_success TEXT,last_attempt TEXT,last_success TEXT,error TEXT,etag TEXT,last_modified TEXT,policy TEXT NOT NULL,count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS items(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),title TEXT NOT NULL,url TEXT NOT NULL UNIQUE,title_key TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',published_at TEXT,collected_at TEXT NOT NULL,kind TEXT NOT NULL,category TEXT NOT NULL,tags TEXT NOT NULL,score REAL NOT NULL,score_detail TEXT NOT NULL,rule_version TEXT NOT NULL,pdf_url TEXT,related_key TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS items_published ON items(published_at DESC);
CREATE INDEX IF NOT EXISTS items_source_date ON items(source_id,published_at);
CREATE INDEX IF NOT EXISTS items_kind_category ON items(kind,category,published_at);
CREATE INDEX IF NOT EXISTS items_score ON items(score DESC);
CREATE INDEX IF NOT EXISTS items_title ON items(title_key);
CREATE VIRTUAL TABLE IF NOT EXISTS item_search USING fts5(id UNINDEXED,title,summary,tokenize='unicode61');
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT NOT NULL,status TEXT NOT NULL,fetched INTEGER NOT NULL DEFAULT 0,inserted INTEGER NOT NULL DEFAULT 0,duplicates INTEGER NOT NULL DEFAULT 0,filtered INTEGER NOT NULL DEFAULT 0,invalid INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE INDEX IF NOT EXISTS runs_source_date ON runs(source_id,started_at);
CREATE TABLE IF NOT EXISTS series(id TEXT PRIMARY KEY,name TEXT NOT NULL,unit TEXT NOT NULL,frequency TEXT NOT NULL,provider TEXT NOT NULL,url TEXT NOT NULL,is_forecast INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'unverified',updated_at TEXT,error TEXT);
CREATE TABLE IF NOT EXISTS observations(series_id TEXT NOT NULL REFERENCES series(id),date TEXT NOT NULL,value REAL NOT NULL,collected_at TEXT NOT NULL,PRIMARY KEY(series_id,date));
CREATE TABLE IF NOT EXISTS indicator_runs(id TEXT PRIMARY KEY,series_id TEXT NOT NULL,started_at TEXT NOT NULL,status TEXT NOT NULL,count INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE TABLE IF NOT EXISTS records(user_id TEXT NOT NULL,item_id TEXT NOT NULL REFERENCES items(id),bookmarked INTEGER NOT NULL DEFAULT 0,read INTEGER NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '',project TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL,PRIMARY KEY(user_id,item_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at TEXT NOT NULL,csrf TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(key_hash TEXT PRIMARY KEY,count INTEGER NOT NULL DEFAULT 0,window_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS collection_lock(id TEXT PRIMARY KEY,owner TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS forecast_releases(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,series_id TEXT NOT NULL,target_period TEXT NOT NULL,released_at TEXT NOT NULL,value REAL NOT NULL,unit TEXT NOT NULL,original_url TEXT NOT NULL,UNIQUE(source_id,series_id,target_period,released_at));
CREATE TABLE IF NOT EXISTS source_candidates(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,method TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unverified',checked_at TEXT,error TEXT,note TEXT NOT NULL);
